import { describe, expect, it } from "vitest";
import { buildPayload, parseQR, sign, slotFor } from "@/lib/qr";

const SID = "12345678-1234-4234-8234-123456789abc";
const SECRET = "test-secret-for-cross-check";

describe("QR payloads (must match the Python backend byte for byte)", () => {
  // Vectors generated by apps/api/app/services/qr_service.py
  it.each([
    [0, "C7gvfzuBFxrqmUAQmmujG-"],
    [7, "m8XXSJlSyghiEGGVy6Jrq8"],
    [12345, "GJELXONLzasz_qdSj8SrbK"],
  ])("slot %i signs identically to the server", async (slot, sig) => {
    expect(await sign(SECRET, SID, slot)).toBe(sig);
    expect(await buildPayload(SECRET, SID, slot)).toBe(`v1.${SID}.${slot}.${sig}`);
  });

  it("parses a valid payload", () => {
    expect(parseQR(`v1.${SID}.7.m8XXSJlSyghiEGGVy6Jrq8`)).toEqual({ sessionId: SID, slot: 7, signature: "m8XXSJlSyghiEGGVy6Jrq8" });
  });

  it.each(["", "hello", "https://example.com", `v2.${SID}.1.m8XXSJlSyghiEGGVy6Jrq8`, `v1.not-a-uuid.1.m8XXSJlSyghiEGGVy6Jrq8`, `v1.${SID}.x.m8XXSJlSyghiEGGVy6Jrq8`, `v1.${SID}.-1.m8XXSJlSyghiEGGVy6Jrq8`, `v1.${SID}.1.short`])(
    "rejects %j",
    (raw) => expect(parseQR(raw)).toBeNull(),
  );

  it("computes slots from time", () => {
    expect(slotFor(1000, 1000, 20)).toBe(0);
    expect(slotFor(1000, 1000 + 19_999, 20)).toBe(0);
    expect(slotFor(1000, 1000 + 20_000, 20)).toBe(1);
  });
});
